"""Instalador: límites de riesgo del agente definidos por el usuario (sin límites por defecto) y apalancamiento máximo opcional

Ejecutar desde la raíz del proyecto:   python instalar_limites_agente.py
Idempotente, sin .bak. Cada archivo debe estar en alguna de las versiones conocidas (la actual de Cristian, o la de
una etapa intermedia del trabajo de Emilio); si alguno tiene cambios distintos, NO se instala nada y se indica cuál.
"""
import base64, hashlib, io, json, os, sys, zipfile

# Hashes de los estados de partida aceptados por archivo (None = el archivo no existía) y archivos que se eliminan.
ACEPTADAS = json.loads("{\"componentes_plataforma/chat/limites.py\": [null], \"componentes_plataforma/chat/panel.py\": [\"d7681e022fc2df5d79dd48458931098033e9d9eb155d17994f63d3a778aea6c0\"], \"componentes_plataforma/vigilancia_terminos/terminos.html\": [\"7d2839ec289ddaf8a4ab8fd42bf7e55a26acae71d3668e182e4ba76254db0a7f\"], \"herramientas_agente/informe_cartera_herramientas/auxiliares.py\": [\"52a30778a70fe8d02a397d1d7bd82daa8969b63df40bb2df3fddef30161abeee\"], \"herramientas_agente/ordenes_herramientas/esquemas.json\": [\"d7419317f749754c77d9c7f0dc31ccdac80e69925dda0675c17d83fdaa7689b5\"], \"nucleo_agente/ordenes/__init__.py\": [\"b87657df1e4ee62a4057ebf7f7e1e84a4c67c1b1e1607396d2b92e177cdad4dc\"], \"nucleo_agente/ordenes/limites.py\": [\"4c3a413b52790c9786aa337d4f9b086a644a3580ccede473b0b968bb2aa9651f\"], \"nucleo_agente/ordenes/mt5_utiles.py\": [\"116e37909547d26685e4ee89673f0d3a2e187aef5687dbb108ab2ef4525bcdbc\"], \"nucleo_agente/ordenes/propuestas.py\": [\"6182a4905ea47d99d0f44862bc577539e83ccc0d3f7e8ea55eaad4cf4a00cf26\"], \"nucleo_agente/ordenes/validacion.py\": [\"89f14998cff65ac9b980aa48182cada330487db86fcfa622a12c76e290c3c9da\"], \"nucleo_agente/vigilancia/gestion.py\": [\"5dc8655257288ff8a09792affff7a9e87f2307291a873546f923ac484fd2ab88\"], \"prompts/sistema.md\": [\"90c932d3b570b927093c91bb7bb691a61e759813d2d4d2abca0effac52a64246\"]}")
ARCHIVOS = ["componentes_plataforma/chat/limites.py", "componentes_plataforma/chat/panel.py", "componentes_plataforma/vigilancia_terminos/terminos.html", "herramientas_agente/informe_cartera_herramientas/auxiliares.py", "herramientas_agente/ordenes_herramientas/esquemas.json", "nucleo_agente/ordenes/__init__.py", "nucleo_agente/ordenes/limites.py", "nucleo_agente/ordenes/mt5_utiles.py", "nucleo_agente/ordenes/propuestas.py", "nucleo_agente/ordenes/validacion.py", "nucleo_agente/vigilancia/gestion.py", "prompts/sistema.md"]
BORRAR = []
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
